import{f as a,D as l,c as r,o as s,k as n,H as o,aq as d,a as i}from"./chunks/framework.CWvjhqVd.js";const k=JSON.parse('{"title":"Löschen von Werten in Tabellen","description":"","frontmatter":{},"headers":[],"relativePath":"technik/adr/ui/adr005-delete-table-values.md","filePath":"technik/adr/ui/adr005-delete-table-values.md"}'),h={name:"technik/adr/ui/adr005-delete-table-values.md"};function u(c,e,g,b,m,f){const t=l("adr-status");return s(),r("div",null,[e[0]||(e[0]=n("h1",{id:"loschen-von-werten-in-tabellen",tabindex:"-1"},[i("Löschen von Werten in Tabellen "),n("a",{class:"header-anchor",href:"#loschen-von-werten-in-tabellen","aria-label":'Permalink to "Löschen von Werten in Tabellen"'},"​")],-1)),e[1]||(e[1]=n("h2",{id:"status",tabindex:"-1"},[i("Status "),n("a",{class:"header-anchor",href:"#status","aria-label":'Permalink to "Status"'},"​")],-1)),o(t,{status:"accepted"}),e[2]||(e[2]=d('<h2 id="kontext" tabindex="-1">Kontext <a class="header-anchor" href="#kontext" aria-label="Permalink to &quot;Kontext&quot;">​</a></h2><p>Es soll vermieden werden, dass der Nutzer bei der Erfassung von Daten innerhalb einer Tabelle bereits (teil-)befüllte Zeilen entfernt, ohne es zu bemerken.</p><h2 id="entscheidung" tabindex="-1">Entscheidung <a class="header-anchor" href="#entscheidung" aria-label="Permalink to &quot;Entscheidung&quot;">​</a></h2><p>Es gibt zwei Arten von Erfassungstabellen mit variablen Zeilen in der Anwendung. Es wird unter den folgenden beiden Use-Cases unterschieden.</p><h3 id="_1-loschen-einer-einzelnen-zeile" tabindex="-1">1. Löschen einer einzelnen Zeile <a class="header-anchor" href="#_1-loschen-einer-einzelnen-zeile" aria-label="Permalink to &quot;1. Löschen einer einzelnen Zeile&quot;">​</a></h3><ul><li><strong>Aktion</strong>: Mittels Icon-Button (z.B. bei Ereignissen)</li><li><strong>Prozess</strong>: <ul><li>Der Nutzer erhält einen Hinweisdialog mit konkretem Kontext zur zu löschenden Zeile.</li><li>Das Löschen muss bestätigt oder kann abgebrochen werden.</li></ul></li><li><strong>Entscheidungsgrundlage</strong>: <ul><li>Das WLS ist das führende System.</li><li>Die Daten werden zuerst im WLS erfasst und dann auf Papier übertragen.</li></ul></li></ul><h3 id="_2-loschen-von-mehreren-zeilen-gleichzeitig" tabindex="-1">2. Löschen von mehreren Zeilen gleichzeitig <a class="header-anchor" href="#_2-loschen-von-mehreren-zeilen-gleichzeitig" aria-label="Permalink to &quot;2. Löschen von mehreren Zeilen gleichzeitig&quot;">​</a></h3><ul><li><strong>Aktion</strong>: Mittels Input, der die gesamte Zeilenanzahl widerspiegelt (z.B. bei Stimmabgabevermerken)</li><li><strong>Prozess</strong>: <ul><li>Der Nutzer erhält einen Hinweisdialog mit dem Kontext, dass Zeilen x-y aufgrund bereits erfasster Daten nicht gelöscht werden können.</li><li>Das Hinweisfenster kann geschlossen werden, aber das Löschen wird verhindert.</li></ul></li><li><strong>Entscheidungsgrundlage</strong>: <ul><li>Nicht das WLS, sondern das Papier ist das führende System.</li><li>Die Daten werden auf Papier erfasst, und das WLS ist eine Abbildung davon.</li><li>Bei Unstimmigkeiten im WLS reicht eine Korrektur in der Anwendung nicht aus; ein erneuter Abgleich mit den Papierdaten ist notwendig.</li></ul></li></ul><h2 id="konsequenzen" tabindex="-1">Konsequenzen <a class="header-anchor" href="#konsequenzen" aria-label="Permalink to &quot;Konsequenzen&quot;">​</a></h2><ul><li>Jede Komponente zur Bearbeitung von Daten als Tabelle aktiviert einen Hinweisdialog, sobald Zeilen mit bereits (teil-)erfassten Daten aus der Tabelle entfernt werden sollen.</li><li>Der Dialog enthält die Information, welche Zeilen das Löschen verhindern.</li><li>Das Löschen mehrerer (teil-)befüllter Zeilen in einem Zuge ist nicht möglich.</li><li>Sind alle zu löschenden Zeilen leer, öffnet sich kein Dialog und sie werden ohne Bestätigung gelöscht.</li></ul>',10))])}const p=a(h,[["render",u]]);export{k as __pageData,p as default};
